"""Build interactive desktop, tablet and mobile views of the standalone snapshot."""
from pathlib import Path
import json
base=Path(__file__).resolve().parent
source=base/'CPN_Seed_Treatment_Preview.html'
app=json.dumps(source.read_text(),ensure_ascii=False).replace('<','\\u003c')
wrapper='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>What’s on Your Seed? — Design previews</title><style>
*{box-sizing:border-box}body{margin:0;background:#e9ede4;color:#203527;font:15px/1.5 Arial,sans-serif}header{padding:24px max(20px,calc((100vw - 1440px)/2));background:#fff;border-top:4px solid #0b6623;border-bottom:1px solid #ccd5c5}h1{margin:0 0 5px;font-size:24px}p{margin:6px 0;color:#536052}.controls{display:flex;flex-wrap:wrap;gap:8px;margin-top:16px}button{font:inherit;min-height:44px;padding:9px 17px;border:1px solid #71816e;border-radius:7px;color:#203527;background:#fff;cursor:pointer}button[aria-pressed=true]{background:#084d1a;color:#fff;border-color:#084d1a}button:focus-visible{outline:3px solid #084d1a;outline-offset:3px}main{padding:24px 16px 36px}.viewport{position:relative;margin:auto;background:#fff;border-radius:10px;box-shadow:0 8px 35px #173e2520;overflow:hidden}iframe{display:block;border:0;transform-origin:top left;background:#f7f7f2}#size{font-size:13px;min-height:20px;margin:12px 0 0;color:#536052}.note{max-width:1440px;margin:0 auto 16px;font-size:14px}footer{max-width:1440px;margin:20px auto 0;color:#536052;font-size:13px}@media(max-width:500px){header{padding:20px 16px}h1{font-size:21px}main{padding:18px 10px}.controls button{padding-inline:12px}}
</style></head><body><header><h1>What’s on Your Seed?</h1><p>Interactive design previews · Crop Protection Network</p><div class="controls" role="group" aria-label="Preview viewport"><button data-view="desktop" aria-pressed="true">Desktop · 1440 px</button><button data-view="tablet" aria-pressed="false">Tablet · 768 px</button><button data-view="mobile" aria-pressed="false">Mobile · 390 px</button></div><p id="size" role="status" aria-live="polite"></p></header><main><p class="note">Use the controls to change screen size. Scroll inside the preview to explore products, filters, ingredients, and the comparison matrix.</p><div class="viewport" id="viewport"><iframe id="preview" title="Seed treatment database interactive preview" width="1440" height="1000"></iframe></div><footer>These views run the complete redesigned HTML and embedded catalog. They are interactive viewport previews, not browser-verified screenshots. The catalog remains a dated snapshot; source and hazard notices appear in the tool.</footer></main><script id="app-source" type="application/json">APP_JSON</script><script>
const sizes={desktop:[1440,1000],tablet:[768,1024],mobile:[390,844]},frame=document.getElementById('preview'),viewport=document.getElementById('viewport');let mode=sizes[location.hash.slice(1)]?location.hash.slice(1):'desktop';
frame.srcdoc=JSON.parse(document.getElementById('app-source').textContent);
function layout(){const [w,h]=sizes[mode],scale=Math.min(1,(document.documentElement.clientWidth-(innerWidth<500?20:32))/w);frame.width=w;frame.height=h;frame.style.transform='scale('+scale+')';viewport.style.width=(w*scale)+'px';viewport.style.height=(h*scale)+'px';for(const b of document.querySelectorAll('[data-view]'))b.setAttribute('aria-pressed',String(b.dataset.view===mode));frame.title=mode+' preview of the seed treatment database';document.getElementById('size').textContent=w+' × '+h+' viewport · '+Math.round(scale*100)+'% display scale';}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.view;history.replaceState(null,'','#'+mode);layout();}));window.addEventListener('resize',layout);window.addEventListener('hashchange',()=>{if(sizes[location.hash.slice(1)])mode=location.hash.slice(1);layout();});layout();
</script></body></html>'''
out=base/'CPN_Design_Previews.html';out.write_text(wrapper.replace('APP_JSON',app))
# Verify the wrapper embeds precisely the validated standalone file.
embedded=out.read_text().split('<script id="app-source" type="application/json">',1)[1].split('</script>',1)[0]
assert json.loads(embedded)==source.read_text()
print(json.dumps({'preview':str(out),'size_bytes':out.stat().st_size,'standalone':str(base/'CPN_Seed_Treatment_Preview.html')}))
